package org.springframework.samples.petclinic.owner;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.LinkedHashMap;
import java.util.Map;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.emptyString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.matchesPattern;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller OwnerRestController
 * (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * <p>
 * WireMock is intentionally NOT used: {@code detect-external-calls --include-di-analysis}
 * found zero external HTTP calls in {@code getOwner} (its only dependency is the internal
 * {@code OwnerRepository}, which is exercised against the REAL database, not mocked).
 * </p>
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetOwnerByIdBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	/** Obtained once in {@link #login()} via POST /api/auth/login; JWTs are stateless so sharing is safe. */
	private static String authToken;

	@BeforeAll
	static void login() {
		Response response = given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract()
			.response();
		authToken = response.jsonPath().getString("token");
	}

	@AfterAll
	static void cleanup() {
		authToken = null;
	}

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	/**
	 * Deterministic numeric id derived from the test method name, offset per fixture row so
	 * that a single test method can insert several related rows (owner/type/pet/visit) without
	 * primary-key collisions, while staying stable across re-runs and distinct across parallel
	 * test methods.
	 */
	private static int numericId(TestInfo info, int offset) {
		int base = Math.abs(info.getTestMethod().get().getName().hashCode()) % 900_000_000 + 100_000_000;
		return base + offset;
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = GetOwnerByIdBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (Map.Entry<String, String> entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	// ============================================================
	// NTC — Happy Path (3 distinct DB shapes, ≥3 per naming rules)
	// ============================================================

	@Test
	void NTC_getOwner_withoutPets(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));
		params.put("FIRST_NAME", "George");
		params.put("LAST_NAME", "NoPets");
		params.put("ADDRESS", "110 W. Liberty St.");
		params.put("CITY", "Madison");
		params.put("TELEPHONE", "6085551023");

		executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		executeSqlTemplate("sql/get-owner-by-id-setup.sql", params);

		try {
			given().log()
				.ifValidationFails()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
			.when()
				.get("/api/owners/{ownerId}", ownerId)
			.then().log()
				.ifValidationFails()
				.statusCode(200)
				.body("id", equalTo(ownerId))
				.body("firstName", equalTo("George"))
				.body("lastName", equalTo("NoPets"))
				.body("address", equalTo("110 W. Liberty St."))
				.body("city", equalTo("Madison"))
				.body("telephone", equalTo("6085551023"))
				.body("pets.size()", equalTo(0));
		}
		finally {
			executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		}
	}

	@Test
	void NTC_getOwner_withSinglePet(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		int typeId = numericId(info, 1);
		int petId = numericId(info, 2);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));
		params.put("FIRST_NAME", "Betty");
		params.put("LAST_NAME", "OnePet");
		params.put("ADDRESS", "638 Cardinal Ave.");
		params.put("CITY", "Sun Prairie");
		params.put("TELEPHONE", "6085551749");
		params.put("TYPE_ID", String.valueOf(typeId));
		params.put("TYPE_NAME", "hamster");
		params.put("PET_ID", String.valueOf(petId));
		params.put("PET_NAME", "Basil");
		params.put("BIRTH_DATE", "2020-09-04");

		executeSqlTemplate("sql/get-owner-by-id-with-pet-teardown.sql", params);
		executeSqlTemplate("sql/get-owner-by-id-with-pet-setup.sql", params);

		try {
			given().log()
				.ifValidationFails()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
			.when()
				.get("/api/owners/{ownerId}", ownerId)
			.then().log()
				.ifValidationFails()
				.statusCode(200)
				.body("id", equalTo(ownerId))
				.body("firstName", equalTo("Betty"))
				.body("lastName", equalTo("OnePet"))
				.body("pets.size()", equalTo(1))
				.body("pets[0].id", equalTo(petId))
				.body("pets[0].name", equalTo("Basil"))
				.body("pets[0].birthDate", equalTo("2020-09-04"))
				.body("pets[0].type.id", equalTo(typeId))
				.body("pets[0].type.name", equalTo("hamster"))
				.body("pets[0].visits.size()", equalTo(0));
		}
		finally {
			executeSqlTemplate("sql/get-owner-by-id-with-pet-teardown.sql", params);
		}
	}

	@Test
	void NTC_getOwner_withPetAndVisit(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		int typeId = numericId(info, 1);
		int petId = numericId(info, 2);
		int visitId = numericId(info, 3);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));
		params.put("FIRST_NAME", "Harold");
		params.put("LAST_NAME", "WithVisit");
		params.put("ADDRESS", "563 Friendly St.");
		params.put("CITY", "Windsor");
		params.put("TELEPHONE", "6085553198");
		params.put("TYPE_ID", String.valueOf(typeId));
		params.put("TYPE_NAME", "dog");
		params.put("PET_ID", String.valueOf(petId));
		params.put("PET_NAME", "Rosy");
		params.put("BIRTH_DATE", "2018-03-06");
		params.put("VISIT_ID", String.valueOf(visitId));
		params.put("VISIT_DATE", "2024-05-12");
		params.put("VISIT_DESC", "rabies shot");

		executeSqlTemplate("sql/get-owner-by-id-with-visit-teardown.sql", params);
		executeSqlTemplate("sql/get-owner-by-id-with-visit-setup.sql", params);

		try {
			given().log()
				.ifValidationFails()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer " + authToken)
			.when()
				.get("/api/owners/{ownerId}", ownerId)
			.then().log()
				.ifValidationFails()
				.statusCode(200)
				.body("id", equalTo(ownerId))
				.body("pets.size()", equalTo(1))
				.body("pets[0].id", equalTo(petId))
				.body("pets[0].visits.size()", equalTo(1))
				.body("pets[0].visits[0].id", equalTo(visitId))
				.body("pets[0].visits[0].date", equalTo("2024-05-12"))
				.body("pets[0].visits[0].description", equalTo("rabies shot"));

			// DB state verification via direct JDBC (per Core Principle 5)
			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn
						.prepareStatement("SELECT description FROM visits WHERE id = ?")) {
				ps.setInt(1, visitId);
				try (ResultSet rs = ps.executeQuery()) {
					assertTrue(rs.next());
					assertEquals("rabies shot", rs.getString("description"));
				}
			}
		}
		finally {
			executeSqlTemplate("sql/get-owner-by-id-with-visit-teardown.sql", params);
		}
	}

	// ============================================================
	// VTC — RED parameter (ownerId, DB_WHERE / path-variable-to-Integer conversion) mutations
	// ============================================================

	/**
	 * ownerId cannot be truly "null" for a required @PathVariable without matching a different
	 * route (GET /api/owners with no trailing segment hits the sibling getAllOwners handler, not
	 * getOwner). The closest faithful equivalent for a mandatory single path segment is an empty
	 * segment (trailing slash), which is exercised here; this covers both the NULL and EMPTY VTC
	 * standard rules for this parameter.
	 */
	@Test
	void VTC_ownerId_NULL_EMPTY() {
		given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
		.when()
			.get("/api/owners/")
		.then().log()
			.ifValidationFails()
			.statusCode(404);
	}

	@Test
	void VTC_ownerId_WHITE_SPACE() {
		given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.urlEncodingEnabled(true)
		.when()
			.get("/api/owners/{ownerId}", " ")
		.then().log()
			.ifValidationFails()
			.statusCode(400)
			.body("status", equalTo(400));
	}

	@Test
	void VTC_ownerId_SPECIAL_CHAR() {
		given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
			.urlEncodingEnabled(true)
		.when()
			.get("/api/owners/{ownerId}", "'; DROP TABLE owners --")
		.then().log()
			.ifValidationFails()
			.statusCode(400)
			.body("status", equalTo(400));

		// DB state verification: the owners table must be unaffected by the injection attempt
		try (Connection conn = getDbConnection(); Statement stmt = conn.createStatement()) {
			ResultSet rs = stmt.executeQuery("SELECT COUNT(*) AS cnt FROM owners");
			assertTrue(rs.next());
			assertTrue(rs.getInt("cnt") >= 0, "owners table must still exist and be queryable");
		}
		catch (Exception e) {
			throw new RuntimeException("DB verification failed", e);
		}
	}

	@Test
	void VTC_ownerId_INVALID_FORMAT() {
		given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
		.when()
			.get("/api/owners/{ownerId}", "not-a-number")
		.then().log()
			.ifValidationFails()
			.statusCode(400)
			.body("status", equalTo(400));
	}

	// ============================================================
	// ATC — Exception paths (business 404 + authentication 403)
	// ============================================================

	@Test
	void ATC_ownerId_noData(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));

		// Defensive teardown only: guarantee no owner exists with this id, no insert performed.
		executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);

		given().log()
			.ifValidationFails()
			.baseUri(BASE_URL)
			.header("Authorization", "Bearer " + authToken)
		.when()
			.get("/api/owners/{ownerId}", ownerId)
		.then().log()
			.ifValidationFails()
			.statusCode(404)
			.body(emptyString());
	}

	@Test
	void ATC_missingAuthorizationHeader(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));
		params.put("FIRST_NAME", "Jean");
		params.put("LAST_NAME", "NoAuth");
		params.put("ADDRESS", "2749 Blackhawk Trail");
		params.put("CITY", "Madison");
		params.put("TELEPHONE", "6085555387");

		executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		executeSqlTemplate("sql/get-owner-by-id-setup.sql", params);

		try {
			given().log()
				.ifValidationFails()
				.baseUri(BASE_URL)
			.when()
				.get("/api/owners/{ownerId}", ownerId)
			.then().log()
				.ifValidationFails()
				.statusCode(403)
				.body("status", equalTo(403));
		}
		finally {
			executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		}
	}

	@Test
	void ATC_invalidAuthorizationToken(TestInfo info) throws Exception {
		int ownerId = numericId(info, 0);
		Map<String, String> params = new LinkedHashMap<>();
		params.put("OWNER_ID", String.valueOf(ownerId));
		params.put("FIRST_NAME", "Peter");
		params.put("LAST_NAME", "BadToken");
		params.put("ADDRESS", "2335 Independence La.");
		params.put("CITY", "Waunakee");
		params.put("TELEPHONE", "6085555487");

		executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		executeSqlTemplate("sql/get-owner-by-id-setup.sql", params);

		try {
			given().log()
				.ifValidationFails()
				.baseUri(BASE_URL)
				.header("Authorization", "Bearer this.is.not.a.valid.jwt")
			.when()
				.get("/api/owners/{ownerId}", ownerId)
			.then().log()
				.ifValidationFails()
				.statusCode(403)
				.body("status", equalTo(403));
		}
		finally {
			executeSqlTemplate("sql/get-owner-by-id-teardown.sql", params);
		}
	}

}

